import { render, screen, fireEvent, waitFor } from '@testing-library/react-native'
import ProfilOlusturEkrani from '../../src/app/profil-olustur'
import { supabase } from '../../lib/supabase'
import { kullaniciAdiMusaitMi } from '../../lib/kullanici-adi'

const mockInsert = jest.fn().mockResolvedValue({ error: null })

jest.mock('../../lib/supabase', () => ({
  supabase: {
    auth: { getUser: jest.fn().mockResolvedValue({ data: { user: { id: 'kullanici-1' } } }) },
    from: jest.fn(() => ({ insert: mockInsert })),
  },
}))

jest.mock('../../lib/kullanici-adi', () => ({
  ...jest.requireActual('../../lib/kullanici-adi'),
  kullaniciAdiMusaitMi: jest.fn(),
}))

const mockRouterReplace = jest.fn()
jest.mock('expo-router', () => ({
  useRouter: () => ({ replace: mockRouterReplace }),
}))

/** Dogum tarihini uc ayri alana yazar. */
async function dogumTarihiniYaz(gun: string, ay: string, yil: string) {
  await fireEvent.changeText(screen.getByPlaceholderText('GG'), gun)
  await fireEvent.changeText(screen.getByPlaceholderText('AA'), ay)
  await fireEvent.changeText(screen.getByPlaceholderText('YYYY'), yil)
}

describe('ProfilOlusturEkrani', () => {
  beforeEach(() => {
    ;(kullaniciAdiMusaitMi as jest.Mock).mockResolvedValue(true)
  })

  it('18 yas altinda dogum tarihinde hata gosterir', async () => {
    await render(<ProfilOlusturEkrani />)
    await fireEvent.changeText(screen.getByPlaceholderText('Seni nasıl çağıralım?'), 'Ada')
    await fireEvent.changeText(screen.getByPlaceholderText('kullaniciadi'), 'ada')
    await dogumTarihiniYaz('01', '01', '2015')
    await fireEvent.press(screen.getByText('Profilimi oluştur'))
    await waitFor(() => {
      expect(
        screen.getByText('Slooin’i kullanmak için 18 yaşını doldurmuş olman gerekiyor.')
      ).toBeTruthy()
    })
    expect(supabase.from).not.toHaveBeenCalled()
  })

  it('takvimde olmayan bir gunu reddeder', async () => {
    await render(<ProfilOlusturEkrani />)
    await fireEvent.changeText(screen.getByPlaceholderText('Seni nasıl çağıralım?'), 'Ada')
    await fireEvent.changeText(screen.getByPlaceholderText('kullaniciadi'), 'ada')
    await dogumTarihiniYaz('31', '02', '1990')
    await fireEvent.press(screen.getByText('Profilimi oluştur'))

    expect(await screen.findByText('Geçerli bir doğum tarihi gir.')).toBeTruthy()
    expect(supabase.from).not.toHaveBeenCalled()
  })

