if (kodAlanlari.length > 0) await kodAlanlari[0].type('123456', { delay: 40 })
await new Promise((r) => setTimeout(r, 8000))
await ekran('4) kod girildi:')

await s.screenshot({ path: process.argv[2] })
await t.close()

