create or replace function gizli.profil_fotografi_guncel_mi(p_yol text)
returns boolean
language plpgsql
security definer
stable
set search_path = public, storage
as $$
declare
  v_sahip uuid;
begin
  begin
    v_sahip := ((storage.foldername(p_yol))[1])::uuid;
  exception when others then
    return false;
  end;

  return exists (
    select 1
    from public.profiller p
    where p.id = v_sahip
      and p_yol = any(p.fotograflar)
  );
end;
$$;

revoke execute on function gizli.profil_fotografi_guncel_mi(text) from public, anon;
grant execute on function gizli.profil_fotografi_guncel_mi(text) to authenticated;

drop policy "baskasinin profil fotografini okuyabilir" on storage.objects;

create policy "baskasinin profil fotografini okuyabilir"
  on storage.objects for select
  to authenticated
  using (
    bucket_id = 'profil-fotograflari'
    and gizli.profil_fotografi_guncel_mi(name)
    and not gizli.engelli_mi(((storage.foldername(name))[1])::uuid)
  );

-- Test hesabinin fotograf alanina GECICI olarak bir yol yaziyoruz,
-- fonksiyonun true dondugunu olcuyoruz ve hemen geri aliyoruz.
do $$
declare
  v_id uuid := 'e9819ec3-ffe8-42a4-86ac-8706d0ce62e9';
  v_yol text := 'e9819ec3-ffe8-42a4-86ac-8706d0ce62e9/gorunurluk-test-1787155799720.txt';
  v_once boolean;
  v_sonra boolean;
  v_yedek text[];
begin
  select fotograflar into v_yedek from public.profiller where id = v_id;
  v_once := gizli.profil_fotografi_guncel_mi(v_yol);

  update public.profiller set fotograflar = array[v_yol] where id = v_id;
  v_sonra := gizli.profil_fotografi_guncel_mi(v_yol);

  update public.profiller set fotograflar = coalesce(v_yedek, '{}') where id = v_id;

  raise notice 'guncel degilken: %  |  guncelken: %  |  geri alindi: %',
    v_once, v_sonra, (select fotograflar from public.profiller where id = v_id);
end $$;

